<?php
declare(strict_types=1);final class Auth{static function user():?array{return $_SESSION['user']??null;}static function check():bool{return self::user()!==null;}static function id():int{return (int)(self::user()['id']??0);}static function requireLogin():void{if(!self::check()){flash('warning','Please sign in.');redirect('login.php');}}static function login(string $email,string $password):bool{$s=db()->prepare("SELECT id,name,email,password_hash,role,status FROM users WHERE email=? LIMIT 1");$s->execute([strtolower(trim($email))]);$u=$s->fetch();if(!$u||$u['status']!=='active'||!password_verify($password,$u['password_hash']))return false;session_regenerate_id(true);unset($u['password_hash']);$_SESSION['user']=$u;db()->prepare('UPDATE users SET last_login_at=NOW() WHERE id=?')->execute([$u['id']]);return true;}static function logout():void{$_SESSION=[];session_destroy();}}
